// KAZI YA KIKOMANDOO: INACHUJA ARRAY NA KUCHORA VIFUNGO KIOONI
function amshaUtafutajiWaKata() {
    const searchField = document.getElementById("explore-search-field");
    const resultsContainer = document.getElementById("search-results-container");

    if (!searchField || !resultsContainer) return;

    // Inasikiliza kila herufi inayoandikwa kwenye simu ya mtumiaji
    searchField.addEventListener("input", (e) => {
        const manenoYaliyoandikwa = e.target.value.trim().toLowerCase();
        resultsContainer.innerHTML = ""; // Inasafisha vifungo vya zamani kiooni upesi

        // Mtumiaji akifuta herufi zote, tunaficha vifungo visijaze kioo bure
        if (manenoYaliyoandikwa.length === 0) {
            return;
        }

        // KICHUJIO CHA KASI YA MWANGA: Kinachuja kata 5,800 ndani ya RAM kwa sekunde sifuri
        const kataZilizofuzu = databaseYaKata.filter(kata => {
            return kata.jina.toLowerCase().includes(manenoYaliyoandikwa) || 
                   kata.wilaya.toLowerCase().includes(manenoYaliyoandikwa);
        });

        // Kama neno lililoandikwa halipo kabisa nchini
        if (kataZilizofuzu.length === 0) {
            resultsContainer.innerHTML = `
                <div class="no-search-match">
                    <i class="fas fa-map-signs"></i> Mtaa au kata hiyo haipo kwenye ramani ya vipaji...
                </div>`;
            return;
        }

        // BINU YA PAGINATION KIOONI: Tunachora kata 15 tu za kwanza zilizofuzu ili kuzuia simu isigande!
        const kataZaKuchora = kataZilizofuzu.slice(0, 15);

        kataZaKuchora.forEach(kata => {
            // Tunatengeneza kitufe cha kikomandoo kwa kila kata
            const kitufe = document.createElement("button");
            kitufe.className = "search-kata-chip-btn";
            
            // Unyofu wa muonekano: mfano "Idiwili (Mbozi)"
            kitufe.innerHTML = `
                <i class="fas fa-map-marker-alt"></i> 
                <strong>${kata.jina}</strong> <span class="district-sub-text">(${kata.wilaya})</span>
            `;

            // AKILI KUU: Mtumiaji akibonyeza tu kifungo hiki, data inatunzwa na kurushwa Explore!
            kitufe.onclick = () => {
                localStorage.setItem("explore_kata_target", kata.jina); // Inatunza jina la kata kwenye simu
                window.location.href = "explore.html"; // Inamtupa mtumiaji explore.html kiotomatiki
            };

            resultsContainer.appendChild(kitufe); // Kitufe kinaruka kiooni papo hapo!
        });
    });
}

// INAAMSHA MTAMBO RASMI MARA TU UKURASA UNAPOFUNGUKA KIOONI
window.addEventListener("DOMContentLoaded", amshaUtafutajiWaKata);
